import { VueConstructor } from 'vue';
import { Component, Prop, Vue } from 'vue-property-decorator';
import { SubMenuManager } from '../../../sub-settings-manager';
import { ISubSettingMenu } from '../../../types';
import SettingsMenuItem from '../../settings-menu/item/index.vue';
import MenuArrow from '../../common/menu-arrow/index.vue';

@Component({
    name: 'SettingsItemSubMenu',
    components: {
        SettingsMenuItem,
        MenuArrow
    }
})
export default class SettingsItemSubMenu extends Vue implements ISubSettingMenu {

    @Prop({
        type: String,
        required: true
    })
    public label: string;

    @Prop({
        type: String,
        required: true
    })
    public id: string;

    @Prop({
        type: [Function, Object],
        required: true
    })
    public component: VueConstructor;

    @Prop({
        type: Function,
        required: false,
        default: null
    })
    public waitFor: null | (() => Promise<{ [key: string]: unknown; }>);

    public isWaiting: boolean = false;

    public created() {
        SubMenuManager.add(this);
    }

    public beforeDestroy() {
        SubMenuManager.remove(this.id);
    }

    public async onClick() {
        try {
            if (this.isWaiting) {
                return;
            }

            if (!this.waitFor) {
                SubMenuManager.open({ id: this.id });
                return;
            }

            this.isWaiting = true;
            const props = await this.waitFor();
            SubMenuManager.open({ id: this.id, props });
            this.isWaiting = false;
        } catch {
            this.isWaiting = false;
        }
    }

    public onBackButtonClick() {
        SubMenuManager.close();
    }
}
